script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { tab: 'pers', cs: '', m: '', errs: {}, mail: 'i.peragov@housebook.ae', tgOn: true, newMail: '', mCode: '', mStep: 1,
    first: 'Илья', last: 'Перагов', birth: '14.03.1986', enF: '', enL: '', wa: '+971 50 123 45 67', country: 'ОАЭ', lang: 'Русский', city: 'Дубай', bio: 'Помогаю семьям из России и СНГ купить жильё у моря: в ОАЭ, Турции и на Кипре. Говорю с клиентом по-человечески и без спешки.',
    co: '', site: '', insta: '', tg: '', coMail: '', coPhone: '', coDesc: '', kind: 'Частное лицо', citizen: 'Россия', taxRes: 'ОАЭ', passNo: HB.isNovice() ? '' : '75 1234567', passBy: HB.isNovice() ? '' : 'ГУ МВД России по г. Москве', passDate: HB.isNovice() ? '' : '21.06.2019', addrCountry: 'ОАЭ', addr: HB.isNovice() ? '' : 'Дубай, Business Bay, ул. Марасси, д. 12, кв. 405' }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  fieldVals(KEYS, MASK, ERR, SEL) {
    const S = this.state, v = {};
    const mask = (s) => { const d = s.replace(/\D/g, '').slice(0, 8); return d.length > 4 ? d.slice(0, 2) + '.' + d.slice(2, 4) + '.' + d.slice(4) : d.length > 2 ? d.slice(0, 2) + '.' + d.slice(2) : d; };
    KEYS.forEach((k) => { v['f_' + k] = S[k]; v['s_' + k] = (e) => this.setState({ [k]: MASK.indexOf(k) >= 0 ? mask(e.target.value) : e.target.value, errs: Object.assign({}, S.errs, { [k]: '' }) }); v['c_' + k] = ERR[k] ? 'is-err' : ''; v['m_' + k] = ERR[k] || ''; });
    Object.keys(SEL).forEach((k) => { v['f_' + k] = S[k]; v['o_' + k] = S.cs === k; v['t_' + k] = () => this.setState({ cs: S.cs === k ? '' : k });
      v['l_' + k] = SEL[k].map((t) => ({ t, sel: S[k] === t, pick: () => this.setState({ [k]: t, cs: '' }) })); });
    return v;
  }

  renderVals() {
    const S = this.state, E = S.errs;
    const OPT = { country: ['ОАЭ', 'Россия', 'Турция', 'Кипр', 'Грузия'], lang: ['Русский', 'English'], citizen: ['Россия', 'Беларусь', 'Казахстан', 'Украина', 'Другая'], taxRes: ['ОАЭ', 'Россия', 'Турция', 'Кипр', 'Другая'], addrCountry: ['ОАЭ', 'Россия', 'Турция', 'Кипр', 'Грузия'] };
    const KEYS = ['first', 'last', 'birth', 'enF', 'enL', 'wa', 'city', 'bio', 'co', 'site', 'insta', 'tg', 'coMail', 'coPhone', 'coDesc', 'passNo', 'passBy', 'passDate', 'addr', 'newMail', 'mCode'];
    const dateOk = (s) => { const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(s); if (!m) return false; const d = +m[1], mo = +m[2], y = +m[3]; return d >= 1 && d <= 31 && mo >= 1 && mo <= 12 && y >= 1900 && y <= 2026; };
    const mailOk = (s) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s.trim());
    const T = [['pers', 'Личные данные'], ['brand', 'Бренд'], ['con', 'Данные для договора'], ['doc', 'Договор']];
    const tabs = T.map(([k, t]) => ({ t, sel: S.tab === k, pick: () => this.setState({ tab: k, cs: '' }) }));
    const miss = []; if (!S.passNo.trim()) miss.push('Номер паспорта'); if (!dateOk(S.passDate)) miss.push('Дата выдачи паспорта'); if (!S.addr.trim()) miss.push('Адрес проживания');
    const KINDS = { 'Частное лицо': 'Договор заключается с Вами лично. Ниже паспортные данные.', 'Компания': 'Договор заключается с компанией. Реквизиты компании понадобятся при подписании.', 'ИП': 'Договор заключается с Вами как с ИП.', 'Самозанятый': 'Договор заключается с Вами как с самозанятым.' };
    const kinds = Object.keys(KINDS).map((t) => ({ t, on: S.kind === t, pick: () => this.setState({ kind: t }) }));
    const done = (errs, msg, e) => { this.setState({ errs }); if (Object.keys(errs).some((k) => errs[k])) { this.say('Проверьте поля, помеченные красным', e); return; }
      if (S.country === 'Не выбрана' && msg.indexOf('Личные') === 0) { this.say('Выберите страну проживания', e); return; }
      const snap = {}; ["first","last","birth","enF","enL","wa","country","lang","city","bio","co","site","insta","tg","coMail","coPhone","coDesc","kind","citizen","taxRes","passNo","passBy","passDate","addrCountry","addr","mail"].forEach((k) => { snap[k] = S[k]; }); HB.store.set('facts.profile', Object.assign({}, HB.store.get('facts.profile') || {}, snap)); this.say(msg, e); };
    const fv = this.fieldVals(KEYS, ['birth', 'passDate'], E, OPT);
    return Object.assign(this.baseVals(), fv, { tabs, tPers: S.tab === 'pers', tBrand: S.tab === 'brand', tCon: S.tab === 'con', tDoc: S.tab === 'doc', mail: S.mail,
      kinds, kindNote: KINDS[S.kind], miss, hasMiss: miss.length > 0, noMiss: miss.length === 0, goDoc: () => this.setState({ tab: 'doc' }), fillGo: () => this.setState({ tab: 'con' }),
      savePers: (e) => { if (e && e.preventDefault) e.preventDefault(); const r = {}; if (!S.first.trim()) r.first = 'Напишите имя'; if (!S.last.trim()) r.last = 'Напишите фамилию'; if (S.birth && !dateOk(S.birth)) r.birth = 'Проверьте дату: например, 14.03.1986'; if (S.wa.replace(/\D/g, '').length < 7) r.wa = 'Номер слишком короткий'; done(r, 'Личные данные сохранены', e); },
      saveBrand: (e) => { if (e && e.preventDefault) e.preventDefault(); const r = {}; if (S.coMail && !mailOk(S.coMail)) r.coMail = 'Проверьте почту'; if (S.site && !/^https?:\/\/\S+\.\S+/.test(S.site)) r.site = 'Адрес начинается с https://'; done(r, 'Бренд сохранён', e); },
      saveCon: (e) => { if (e && e.preventDefault) e.preventDefault(); const r = {}; if (!S.passNo.trim()) r.passNo = 'Нужно для договора'; if (!dateOk(S.passDate)) r.passDate = 'Введите дату выдачи: ДД.ММ.ГГГГ'; if (!S.addr.trim()) r.addr = 'Нужно для договора'; done(r, 'Данные для договора сохранены', e); },
      sayPhoto: (e) => this.say('Фото загружено', e), sayLogo: (e) => this.say('Логотип загружен', e), sayMic: (e) => this.say('Включится микрофон, говорите', e), sayGoogle: (e) => this.say('В кабинете откроется вход через Google', e),
      aiBio: (e) => { this.setState({ bio: 'Подбираю жильё у моря для семей из России и СНГ: ОАЭ, Турция, Кипр. Объясняю просто, без спешки, и сопровождаю до ключей.' }); this.say('Текст готов, поправьте под себя', e); },
      aiDesc: (e) => { this.setState({ coDesc: 'Помогаем семьям купить жильё за рубежом: подбор, сопровождение сделки, понятные цены.' }); this.say('Текст готов, поправьте под себя', e); },
      tgText: S.tgOn ? (HB.isNovice() ? 'Подключён. ' : 'Подключён: @ilya_peragov. ') + 'Статусы клиентов и быстрые команды.' : 'Не подключён. Статусы клиентов придут сюда.', tgLabel: S.tgOn ? 'Отключить' : 'Подключить',
      tgBtn: (e) => { if (S.tgOn) this.openM('tg', e); else { this.setState({ tgOn: true }); this.say('Telegram подключён', e); } }, tgOff: (e) => { this.setState({ tgOn: false, m: '' }); this.say('Telegram отключён', e); },
      m_mail: S.m === 'mail', m_tg: S.m === 'tg', mStep1: S.mStep === 1, mStep2: S.mStep === 2, mailOpen: (e) => this.openM('mail', e, { mStep: 1, newMail: '', mCode: '', errs: {} }),
      mailSend: (e) => { if (!mailOk(S.newMail)) { this.setState({ errs: { newMail: 'Проверьте почту' } }); return; } this.setState({ mStep: 2, errs: {} }); },
      mailOk: (e) => { if (S.mCode.trim() !== '123456') { this.setState({ errs: { mCode: 'Код не подошёл. Проверьте письмо' } }); return; } this.setState({ mail: S.newMail.trim(), m: '' }); this.say('Почта изменена', e); } });
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); const pr = HB.store.get('facts.profile') || {};
    if (HB.isNovice()) Object.assign(this.state, { first: 'Илья', last: 'Перагов', birth: '', wa: '', country: 'Не выбрана', city: '', bio: '', mail: 'i.peragov@housebook.ae', tgOn: false, passNo: '', passDate: '', addr: '' });
    ["first","last","birth","enF","enL","wa","country","lang","city","bio","co","site","insta","tg","coMail","coPhone","coDesc","kind","citizen","taxRes","passNo","passBy","passDate","addrCountry","addr","mail"].forEach((k) => { if (pr[k] != null) this.state[k] = pr[k]; }); }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); const sg = !!HB.store.get('facts.contractSigned'); v.isSigned = sg; v.notSigned = !sg; v.missD = !sg && v.hasMiss; v.noMissD = !sg && v.noMiss; return v; }
}; })(Component);
